#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> sortWordsByWeight(std::vector<std::string>& words, std::vector<int>& weights) {
        auto getWeight = [&](const std::string& w) {
            long long sum = 0;
            for (char c : w) sum += weights[c - 'a'];
            return sum;
        };
        std::vector<std::string> res = words;
        std::sort(res.begin(), res.end(), [&](const std::string& a, const std::string& b) {
            long long wa = getWeight(a), wb = getWeight(b);
            if (wa != wb) return wa < wb;
            return a < b;
        });
        return res;
    }
};

import java.util.*;

class Solution {
    public String[] sortWordsByWeight(String[] words, int[] weights) {
        String[] res = words.clone();
        Arrays.sort(res, (a, b) -> {
            long wa = 0, wb = 0;
            for (char c : a.toCharArray()) wa += weights[c - 'a'];
            for (char c : b.toCharArray()) wb += weights[c - 'a'];
            if (wa != wb) return Long.compare(wa, wb);
            return a.compareTo(b);
        });
        return res;
    }
}

function sortWordsByWeight(words, weights) {
    const getWeight = (w) => {
        let sum = 0;
        for (let i = 0; i < w.length; i++) {
            sum += weights[w.charCodeAt(i) - 97];
        }
        return sum;
    };
    return [...words].sort((a, b) => {
        const wa = getWeight(a);
        const wb = getWeight(b);
        if (wa !== wb) return wa - wb;
        return a.localeCompare(b);
    });
}
